import{_ as o,a0 as a,w as r,s as I,ao as u,I as e,x as t,a1 as l,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"UNIGINE 可能是 Linux 上最好的游戏引擎 | LCTT x X-CMD","titleTemplate":false,"description":"UNIGINE 可能是 Linux 上最好的游戏引擎 | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"UNIGINE 可能是 Linux 上最好的游戏引擎 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"UNIGINE 可能是 Linux 上最好的游戏引擎 | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/UNIGINE Is Probably the Best Gaming Engine on Linux","title":"UNIGINE 可能是 Linux 上最好的游戏引擎","tag":"201312","desc":""},"relativePath":"201312/UNIGINE Is Probably the Best Gaming Engine on Linux.md","filePath":"[post].md"}'),p={name:"201312/UNIGINE Is Probably the Best Gaming Engine on Linux.md"};function N(m,n,g,d,x,G){const i=a("Link");return r(),I("div",null,[n[14]||(n[14]=u('<h1 id="unigine-可能是-linux-上最好的游戏引擎" tabindex="-1">UNIGINE 可能是 Linux 上最好的游戏引擎 <a class="header-anchor" href="#unigine-可能是-linux-上最好的游戏引擎" aria-label="Permalink to “UNIGINE 可能是 Linux 上最好的游戏引擎”">​</a></h1><p><strong>UNIGINE，是一个实时的 3D 引擎，它能够在所有主流的平台上运行，包括 Linux，并刚刚升级到新的版本，带给了我们一些重要的新特性。</strong></p><p><img src="http://i1-news.softpedia-static.com/images/news2/UNIGINE-Is-Probably-the-Best-Gaming-Engine-on-Linux-404484-2.jpg" alt=""></p><p>Unigine 引擎正是由 Unigine 公司开发的， 同时这公司还开发了 Heaven DX11 基准测试软件。 这公司开发的技术总是越来越好，并且随着他们最近在 Linux 平台上的扩展，我们真的很高兴看到这引擎在最近时间作出的重大的更新。</p><p>在 UNIGINE 引擎最近作出的更新中，最大的更新是通用图像生成器接口 (Common Image Generator Interface/CIGI) 协议。</p><p>据引擎的开发者说，这个接口在模拟行业中，是一种用于主机设备与图像生成器 (IG) 之间通信的标准方法来的。</p><h3 id="新款-unigine-引擎的亮点" tabindex="-1">新款 UNIGINE 引擎的亮点 <a class="header-anchor" href="#新款-unigine-引擎的亮点" aria-label="Permalink to “新款 UNIGINE 引擎的亮点”">​</a></h3><ul><li>在笛卡尔坐标系中增加了对 WGS84，ECF 和 NED 坐标系的支持（这会帮助开发者更好地在用 Unigine 开发的项目中使用实时的 GIS 数据）；</li><li>实施了游戏框架，这样使得游戏更加容易地创建，同时这种特性包括实体与节点的自动链接、层次与世界的自动链接、实体对象管理、贯穿所有层次的游戏全局上下文、事件处理系统、最佳的实体更新等等。</li><li>增加渲染时帧率的稳定性。</li><li>两个新的选项，2D 噪音和 3D 噪音（编辑器中的状态选项卡），已被添加到 mesh_leaf_base 材质中。</li><li>一个新的参数，遮挡屏蔽，已经被添加到所有的材质中。</li><li>密杂草丛的高度现已实现同步。</li><li>修复了在渲染非 Flash 闪屏时崩溃的漏洞。</li></ul>',8)),e("p",null,[n[1]||(n[1]=t("所有平台的完整新特性列表，可以在官方的",-1)),l(i,{href:"http://www.unigine.com/devlog/2013/11/27/113"},{default:s(()=>[...n[0]||(n[0]=[t("公告",-1)])]),_:1}),n[2]||(n[2]=t("中找到。.",-1))]),n[15]||(n[15]=e("p",null,"要记住 UNIGINE 引擎只针对商业企业，并不向广大用户提供试用版。",-1)),n[16]||(n[16]=e("hr",null,null,-1)),e("p",null,[n[4]||(n[4]=t("via: ",-1)),l(i,{href:"http://news.softpedia.com/news/UNIGINE-Is-Probably-the-Best-Gaming-Engine-on-Linux-404484.shtml"},{default:s(()=>[...n[3]||(n[3]=[t("http://news.softpedia.com/news/UNIGINE-Is-Probably-the-Best-Gaming-Engine-on-Linux-404484.shtml",-1)])]),_:1})]),e("p",null,[n[7]||(n[7]=t("译者：",-1)),l(i,{href:"https://github.com/hyaocuk"},{default:s(()=>[...n[5]||(n[5]=[t("hyaocuk",-1)])]),_:1}),n[8]||(n[8]=t(" 校对：",-1)),l(i,{href:"https://github.com/wxy"},{default:s(()=>[...n[6]||(n[6]=[t("wxy",-1)])]),_:1})]),e("p",null,[n[11]||(n[11]=t("本文由 ",-1)),l(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...n[9]||(n[9]=[t("LCTT",-1)])]),_:1}),n[12]||(n[12]=t(" 原创翻译，",-1)),l(i,{href:"http://linux.cn/"},{default:s(()=>[...n[10]||(n[10]=[t("Linux中国",-1)])]),_:1}),n[13]||(n[13]=t(" 荣誉推出",-1))])])}const T=o(p,[["render",N]]);export{L as __pageData,T as default};
